from scipy.stats import rankdata,beta
p=pd.read_csv(OUT/'conditional_test1_pvalues.csv',dtype={'target':str});p=p[p.target=='v7'];a=pd.read_csv(OUT/'conditional_author_annual_long.csv',dtype={'target':str},low_memory=False);a=a[a.target=='v7'];g={k:v for k,v in a.groupby(['station','index','model'])};rng=np.random.default_rng(20261107);rows=[]
