 aa=g[r['station'],r['index'],'Observed'];bb=g[r['station'],r['index'],r['model']];lo,hi=PER[r['period']];x=aa[aa.year.between(lo,hi)].value.dropna().to_numpy();y=bb[bb.year.between(lo,hi)].value.dropna().to_numpy();ranks=rankdata(np.r_[x,y]);n=len(x);expected=n*(len(ranks)+1)/2;actual=abs(sum(ranks[:n])-expected);N=19999;random=rng.permuted(np.broadcast_to(ranks,(N,len(ranks))),axis=1);s=np.abs(random[:,:n].sum(axis=1)-expected);k=int(sum(s>=actual-1e-12));pmc=(k+1)/(N+1);lower=beta.ppf(.025,k,N-k+1) if k else 0.;upper=beta.ppf(.975,k+1,N-k) if k<N else 1.;rows.append(dict(station=r['station'],index=r['index'],model=r['model'],period=r['period'],asymptotic=r['p'],no_cc=r['p_no_cc'],permutations=N,extreme=k,p_mc=pmc,p_mc_lower=lower,p_mc_upper=upper,decision='ambiguous' if lower<.05<upper else ('pass' if lower>=.05 else 'fail'),different_point_decision=(pmc>=.05)!=(r['p']>=.05)))
